// Golden example: pick the body a new chart follows. Nothing is chosen at first, so the trigger shows a
// placeholder. Validation is Base UI's own: Form runs each field's check on submit, blocks the submit,
// focuses the first invalid control, and Field.Error match="valueMissing" says what to fix. Root gets
// `items` so the trigger shows the label, not the raw value. Spacing is token variables only.
import { useState } from "react";
import { Form } from "@base-ui/react/form";
import { Button, Field, Select } from "../index";

const INNER = { mercury: "Mercury", venus: "Venus", mars: "Mars" };
const OUTER = { jupiter: "Jupiter", saturn: "Saturn", neptune: "Neptune" };
const ITEMS: Record<string, string> = { ...INNER, ...OUTER };

export default function NewChart() {
  const [made, setMade] = useState<string | null>(null);

  return (
    <Form
      onFormSubmit={(values) => setMade(ITEMS[String(values.body)] ?? null)}
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--space-20)",
      }}
    >
      <Field.Root name="body">
        <Field.Label>Body</Field.Label>
        <Select.Root items={ITEMS} required onValueChange={() => setMade(null)}>
          <Select.Trigger placeholder="Choose a body" />
          <Select.Popup>
            <Select.Group>
              <Select.GroupLabel>Inner planets</Select.GroupLabel>
              {Object.entries(INNER).map(([value, label]) => (
                <Select.Item key={value} value={value}>
                  {label}
                </Select.Item>
              ))}
            </Select.Group>
            <Select.Separator />
            <Select.Group>
              <Select.GroupLabel>Outer planets</Select.GroupLabel>
              {Object.entries(OUTER).map(([value, label]) => (
                <Select.Item key={value} value={value}>
                  {label}
                </Select.Item>
              ))}
            </Select.Group>
          </Select.Popup>
        </Select.Root>
        <Field.Description>
          The chart centres on this body and follows its orbit.
        </Field.Description>
        <Field.Error match="valueMissing">
          Choose a body for the chart to follow.
        </Field.Error>
      </Field.Root>
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: "var(--space-12)",
        }}
      >
        <Button variant="primary" type="submit">
          Make chart
        </Button>
        <span role="status">{made ? `Chart made for ${made}.` : ""}</span>
      </div>
    </Form>
  );
}

// Golden example: chart settings. Two settings that stay on or off, each named for what turns on, saved with the
// form. An on switch submits its name with the value "on"; an off switch submits nothing, as a native checkbox.
// Spacing is token variables only.
import { useState } from "react";
import { Form } from "@base-ui/react/form";
import { Button, Field, Switch } from "../index";

export default function ChartSettings() {
  const [saved, setSaved] = useState(false);

  return (
    <Form
      onFormSubmit={() => setSaved(true)}
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--space-20)",
      }}
    >
      <Field.Root>
        <Field.Label>
          <Switch name="gridLines" defaultChecked />
          Show grid lines
        </Field.Label>
      </Field.Root>
      <Field.Root>
        <Field.Label>
          <Switch name="orbitEmails" />
          Email me when an orbit changes
        </Field.Label>
        <Field.Description>At most one email a day.</Field.Description>
      </Field.Root>
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: "var(--space-12)",
        }}
      >
        <Button variant="primary" type="submit">
          Save settings
        </Button>
        <span role="status">{saved ? "Settings saved." : ""}</span>
      </div>
    </Form>
  );
}

// Golden example: an orbit's detail view. Three views of one orbit, read one at a time, the list named by the
// visible heading. Each Tab has a Panel with the same value. Spacing is token variables only.
import { Tabs } from "../index";

export default function OrbitDetail() {
  return (
    <section
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--space-12)",
      }}
    >
      <h2 id="orbit-detail-title" style={{ margin: 0 }}>
        Luna
      </h2>
      <Tabs.Root defaultValue="overview">
        <Tabs.List aria-labelledby="orbit-detail-title">
          <Tabs.Tab value="overview">Overview</Tabs.Tab>
          <Tabs.Tab value="passes">Passes</Tabs.Tab>
          <Tabs.Tab value="history">History</Tabs.Tab>
        </Tabs.List>
        <Tabs.Panel value="overview">
          <p style={{ margin: 0 }}>Period 27.3 days. Tidally locked.</p>
        </Tabs.Panel>
        <Tabs.Panel value="passes">
          <p style={{ margin: 0 }}>Next close pass in four days.</p>
        </Tabs.Panel>
        <Tabs.Panel value="history">
          <p style={{ margin: 0 }}>
            Charted since March, edited by three people.
          </p>
        </Tabs.Panel>
      </Tabs.Root>
    </section>
  );
}

// Golden example: a note on a support request. The note explains what helps up front and says what to fix
// in words when it is empty. Spacing is token variables only.
import { useState, type FormEvent } from "react";
import { Button, Field, Textarea } from "../index";

export default function SupportNote() {
  const [note, setNote] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [sent, setSent] = useState(false);

  function submit(event: FormEvent) {
    event.preventDefault();
    const problem = note.trim()
      ? null
      : "Write a few words about what went wrong.";
    setError(problem);
    setSent(!problem);
  }

  return (
    <form
      noValidate
      onSubmit={submit}
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--space-20)",
      }}
    >
      <Field.Root name="note" invalid={error !== null}>
        <Field.Label>What happened</Field.Label>
        <Textarea
          rows={4}
          value={note}
          onValueChange={(value) => {
            setNote(value);
            setSent(false);
          }}
        />
        <Field.Description>
          Say what you clicked and what you expected. We read every note.
        </Field.Description>
        <Field.Error match={error !== null}>{error}</Field.Error>
      </Field.Root>
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: "var(--space-12)",
        }}
      >
        <Button variant="primary" type="submit">
          Send note
        </Button>
        <span role="status">{sent ? "Note sent." : ""}</span>
      </div>
    </form>
  );
}
